def scoreOfParentheses(s):
    MOD = 10**9 + 7
    # every stack entry is [total so far inside this bracket, is it still empty]
    total = 0
    stack = []
    cur = 0
    for i, ch in enumerate(s):
        if ch == '(':
            stack.append(cur)
            cur = 0
        else:
            inner = cur
            cur = stack.pop()
            if s[i - 1] == '(':
                cur = (cur + 1) % MOD
            else:
                cur = (cur + 2 * inner) % MOD
    return cur % MOD
